									dp[i][j][k]+=(dp[ii][jj][k-1]*c[A-ii][i-ii]*c[B-jj][j-jj])%mod;
									dp[i][j][k]%=mod;
								}
							}
						}
					}
				}
				if(dp[0][0][k]){
					printf("%d\n",k);
					printf("%lld\n",dp[0][0][k]);
					return 0;
				}
			}
		}
	}
	puts("-1\n0");
}
